<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Batch;

use Override;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionCursor;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskContext;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskCounterInterface;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskReaderInterface;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\List\ThemeVersionListUsecase;

class ThemeVersionTaskReader implements TaskReaderInterface, TaskCounterInterface
{
    public function __construct(private readonly ThemeVersionListUsecase $usecase)
    {

    }
    #[Override]
    public function read(TaskContext $context): array
    {
        $filter = $context->params['filter'];
        $cursor = $context->cursor;
        $result = $this->usecase->list($filter, $cursor ?? new ThemeVersionCursor(limit: 1));
        $context->cursor = $result->cursor();
        return $result->values();
    }

    #[Override]
    public function expectedTotal(TaskContext $context): int
    {
        $filter = $context->params['filter'];
        return $this->usecase->count($filter);
    }
}
